function totalSpent() {
  return state.expenses.reduce((sum, e) => sum + e.amount, 0);
}

function renderTotal() {
  totalEl.textContent = "$" + totalSpent().toFixed(2);
}

// Returns a positive number, or null if the field is empty or invalid
function readAmount() {
  const value = parseFloat(amountInput.value);
  return Number.isFinite(value) && value > 0 ? value : null;
}

// Build the dropdown options from the CATEGORIES array
categorySelect.innerHTML = CATEGORIES
  .map((name) => `<option value="${name}">${name}</option>`)
  .join("");

addBtn.addEventListener("click", () => {
  const amount = readAmount();
  amountInput.classList.toggle("invalid", amount === null);
  if (amount === null) return;

  const category = categorySelect.value;
  state.expenses = [
    { id: Date.now(), title: titleInput.value.trim() || category, amount, category },
    ...state.expenses,
  ];
  state.filter = "All"; // make sure the new expense is visible
  titleInput.value = "";
  amountInput.value = "";
  render();
});

// Only the expenses that match the selected chip
function visibleExpenses() {
  if (state.filter === "All") return state.expenses;
  return state.expenses.filter((e) => e.category === state.filter);
}

// One listener on the container; closest() finds which chip was clicked
chipsEl.addEventListener("click", (event) => {
  const chip = event.target.closest("[data-filter]");
  if (!chip) return;
  state.filter = chip.dataset.filter;
  render();
});

function renderList() {
  const items = visibleExpenses();
  if (items.length === 0) {
    listEl.innerHTML = `<div class="empty">No expenses here yet.</div>`;
    return;
  }
  listEl.innerHTML = items
    .map((e) => `
      <li>
        <div class="meta"><div class="name">${esc(e.title)}</div><div class="cat">${e.category}</div></div>
        <span class="amt">$${e.amount.toFixed(2)}</span>
        <button data-delete="${e.id}" data-explain="delete-button" aria-label="Delete">✕</button>
      </li>`)
    .join("");
}

// One listener on the whole list handles every delete button, even ones added later
listEl.addEventListener("click", (event) => {
  const btn = event.target.closest("[data-delete]");
  if (!btn) return;
  const id = Number(btn.dataset.delete);
  state.expenses = state.expenses.filter((e) => e.id !== id);
  render();
});
